function renderSheet(tab){
 const area=$("#cmdSceneOptions");if(!area)return;
 const previousScroll=area.scrollTop;
 const previousScroller=area.closest(".cmd-scene-options-scroll");
 const outerScroll=previousScroller?.scrollTop;
 area.innerHTML=contents(tab);applyOriginalSheets();applyScreenshotCatalogue();
 area.scrollTop=previousScroll;
 if(previousScroller&&outerScroll!=null)previousScroller.scrollTop=outerScroll;

 /* The profile editor is 2D: do not launch the old 3D preview renderer. */
 area.querySelectorAll("[data-sticker-category]").forEach(el=>el.addEventListener("click",()=>{const category=el.dataset.stickerCategory;const n=Number(el.dataset.stickerIndex);if(!Number.isInteger(n))return;const target={vestes:"top",chapeaux:"accessory",lunettes:"accessory",cheveux:"hair",barbes:"beard",piercings:"piercing"}[category];if(!target)return;const options={vestes:clothes,chapeaux:[["hat"],["cap"]],lunettes:[["glasses"],["sunglasses"]],cheveux:[["short"],["long"],["curly"],["ponytail"],["bob"],["shaved"]],barbes:[["none"],["mustache"],["goatee"],["stubble"],["long"]],piercings:piercings}[category];if(Array.isArray(options)&&options.length){const option=options[n%options.length];if(Array.isArray(option))state[target]=option[0]}el.closest(".cmd-original-gallery")?.querySelectorAll(".cmd-original-gallery-tile").forEach(tile=>tile.classList.toggle("selected",tile===el));refreshEditor()}));
 area.querySelectorAll("[data-avatar-part]").forEach(e=>e.addEventListener("click",()=>{avatarPart=e.dataset.avatarPart;renderSheet("avatar");area.scrollTop=0;const scroll=area.closest(".cmd-scene-options-scroll");if(scroll)scroll.scrollTop=0}));
 $$("[data-groom-key]",area).forEach(e=>e.addEventListener("click",()=>{const key=e.dataset.groomKey;const value=e.dataset.groomStyle;if(!["hair","beard"].includes(key))return;state[key]=value;state.avatarStyle="2d";state.avatarModel="civilian";renderSheet("avatar");refreshEditor()}));
 $$("[data-universe-tab]",area).forEach(e=>e.addEventListener("click",()=>{universeCategory=e.dataset.universeTab;renderSheet(tab)}));
 $$("[data-universe-name]",area).forEach(e=>e.addEventListener("input",()=>{state.petName=e.value.slice(0,40)}));
 $$("[data-universe-privacy]",area).forEach(e=>e.addEventListener("change",()=>{state.hideHome=e.checked}));
 $$("[data-scene-field]",area).forEach(e=>e.addEventListener("input",()=>{state[e.dataset.sceneField]=e.value;refreshEditor()}));
 $$("[data-scene-choice]",area).forEach(e=>e.addEventListener("click",()=>{state[e.dataset.sceneChoice]=e.dataset.value;if(e.dataset.sceneChoice==="pet"){state.petStyle="2d";state.petModel=state.pet==="bird"?"parrot":state.pet}if(e.dataset.sceneChoice==="gender"||e.dataset.sceneChoice==="hair"){state.avatarStyle="3d";state.avatarModel="civilian"}renderSheet(tab);refreshEditor()}));
 $$("[data-scene-color]",area).forEach(e=>e.addEventListener("click",()=>{state[e.dataset.sceneColor]=e.dataset.value;renderSheet(tab);refreshEditor()}));
 $$("[data-look-category]",area).forEach(e=>e.addEventListener("click",()=>{lookCategory=e.dataset.lookCategory;renderSheet(tab)}));
 $$("[data-look]",area).forEach(e=>e.addEventListener("click",()=>{const look=looks[Number(e.dataset.look)];if(!look)return;for(const key of ["top","topColor","bottom","shoes","accessory"])state[key]=look[key];renderSheet(tab);refreshEditor()}));
 $$("[data-imported-avatar]",area).forEach(button=>button.addEventListener("click",()=>{state.avatarPreset="reference-avatar-"+button.dataset.importedAvatar;state.avatarStyle="2d";renderSheet("avatar");refreshEditor()}));
 $$("[data-avatar-preset]",area).forEach(button=>button.addEventListener("click",()=>{
  const p=avatarPresets.find(p=>p.id===button.dataset.avatarPreset);if(!p)return;
  Object.assign(state,{avatarPreset:p.id,avatarModel:p.model,gender:p.gender,avatarStyle:"3d",top:p.top,bottom:p.bottom,topColor:p.topColor,skin:p.skin,hair:p.hair,hairColor:p.hairColor,beard:p.beard||"none",beardColor:p.beardColor||p.hairColor,accessory:"none"});
  renderSheet("avatar");refreshEditor();
 }));
}
