 const hero=$("#cmdSceneHero");if(hero){hero.dataset.scene=state.scene;const original=sceneReferenceIndex(state.scene)>=0;const bg=original?sceneTiles[sceneReferenceIndex(state.scene)]:(state.scene==="custom"?custom:scenePhotoUrls[state.scene]);hero.style.backgroundImage=bg?'url("'+String(bg).replace(/"/g,"")+'")':"";hero.style.backgroundSize=original?"contain":"cover";hero.style.backgroundPosition="center";hero.style.backgroundRepeat="no-repeat";hero.style.setProperty("--cmd-personal-scene-image",bg?'url("'+String(bg).replace(/"/g,"")+'")':"none")}
 document.dispatchEvent(new CustomEvent("cmd-avatar-3d:update"));
